package app.truemotion.port;
import org.json.*;
import org.mozilla.javascript.*;
import org.mozilla.javascript.ast.*;
import org.mozilla.javascript.debug.*;
import java.util.*;
/** A command produces a validated JSON edit plan; no Java objects enter JS. */
public final class PluginRuntime {
 static final class Limit extends Error{Limit(String s){super(s);}}
 static final class Budget{long start=System.nanoTime(),limit=2_000_000_000L;int instructions,max=1000000;final ArrayDeque<Scriptable> scopes=new ArrayDeque<Scriptable>();void check(){if(System.nanoTime()-start>limit||instructions>max)throw new Limit("Plugin execution exceeded its budget");for(Scriptable scope:scopes)for(Object key:scope.getIds()){Object value=key instanceof String?scope.get((String)key,scope):null;if(value instanceof CharSequence&&((CharSequence)value).length()>1048576||value instanceof NativeArray&&((NativeArray)value).getLength()>50000)throw new Limit("Plugin value is too large");}}}
 static final ThreadLocal<Budget> budget=new ThreadLocal<Budget>();
 static final ContextFactory factory=new ContextFactory(){protected Context makeContext(){Context c=super.makeContext();c.setOptimizationLevel(-1);c.setLanguageVersion(Context.VERSION_ES6);c.setInstructionObserverThreshold(100);c.setMaximumInterpreterStackDepth(128);c.setClassShutter(name->false);c.setGeneratingDebug(true);c.setDebugger(new Debugger(){public void handleCompilationDone(Context c,DebuggableScript d,String s){}public DebugFrame getFrame(Context c,DebuggableScript d){return new DebugFrame(){Scriptable scope;public void onEnter(Context c,Scriptable a,Scriptable self,Object[] args){scope=a;budget.get().scopes.addLast(a);budget.get().check();}public void onLineChange(Context c,int line){budget.get().check();}public void onExceptionThrown(Context c,Throwable e){}public void onExit(Context c,boolean throwing,Object r){budget.get().scopes.removeLastOccurrence(scope);}public void onDebuggerStatement(Context c){}};}},null);return c;}protected void observeInstructionCount(Context c,int n){budget.get().instructions+=n;budget.get().check();}};
 static final String API="var exports={commands:{}};var project=JSON.parse(__context);var settings=JSON.parse(__settings);var args=JSON.parse(__args);var __ops=[],__logs=[];var api={version:1,project:project,settings:settings,layer:function(id){for(var i=0;i<project.layers.length;i++)if(project.layers[i].id===String(id))return project.layers[i];return null;},log:function(s){if(__logs.length<100)__logs.push(String(s).slice(0,2000));},addShape:function(data){var id='new:'+(__ops.length+1);__ops.push({op:'addShape',id:id,data:data});return id;},addText:function(data){data.kind='text';return this.addShape(data);},setTransform:function(id,data){__ops.push({op:'transform',id:String(id),data:data});},setKeys:function(id,property,keys){__ops.push({op:'keys',id:String(id),property:property,keys:keys});},rename:function(id,name){__ops.push({op:'rename',id:String(id),name:String(name)});},shift:function(id,seconds){__ops.push({op:'shift',id:String(id),seconds:seconds});},addEffect:function(id,effect,params){__ops.push({op:'effect',id:String(id),effect:effect,params:params||{}});}};eval=undefined;RegExp=undefined;Date=undefined;ArrayBuffer=undefined;Uint8Array=undefined;Int8Array=undefined;Uint16Array=undefined;Int16Array=undefined;Uint32Array=undefined;Int32Array=undefined;Float32Array=undefined;Float64Array=undefined;var __fp=Function.prototype;__fp.constructor=function(){throw Error('Dynamic compilation is unavailable');};Function=__fp.constructor;Function.prototype=__fp;String.prototype.repeat=function(n){n=Math.floor(n);if(n<0||n>8192||this.length*n>1048576)throw Error('String is too large');var out='';while(n-->0)out+=this;return out;};String.prototype.match=String.prototype.search=function(){throw Error('Regular expressions are unavailable');};";
 public static JSONObject run(String source,String command,JSONObject context,JSONObject settings,JSONObject args){return execute(source,command,context,settings,args,new JSONObject(),false);}
 public static JSONObject hook(String source,String event,JSONObject context,JSONObject settings,JSONObject data,JSONObject state){return execute(source,event,context,settings,data,state,true);}
 static JSONObject execute(String source,String command,JSONObject context,JSONObject settings,JSONObject args,JSONObject state,boolean hook){if(source.length()>262144)throw new IllegalArgumentException("Plugin source is too large");Budget b=new Budget();if(hook){b.limit=150_000_000L;b.max=40000;}budget.set(b);Context cx=factory.enterContext();try{
  new Parser().parse(source,"plugin.js",1).visit(node->{if(node.getType()==Token.REGEXP)throw new Limit("Regular expressions are unavailable");return true;});
  ScriptableObject scope=cx.initSafeStandardObjects();ScriptableObject.putProperty(scope,"__context",context.toString());ScriptableObject.putProperty(scope,"__settings",settings.toString());ScriptableObject.putProperty(scope,"__args",args.toString());ScriptableObject.putProperty(scope,"__command",command);
  ScriptableObject.putProperty(scope,"__state",state.toString());b.start=System.nanoTime();cx.evaluateString(scope,API+"exports.hooks={};api.version=2;api.state=JSON.parse(__state);api.event=args;","plugin-api",1,null);cx.evaluateString(scope,source,"plugin.js",1,null);cx.evaluateString(scope,hook?"if(typeof exports.hooks[__command]!=='function')throw Error('Hook is not exported');exports.hooks[__command](api,args,settings);":"if(typeof exports.commands[__command]!=='function')throw Error('Command is not exported');exports.commands[__command](api,args,settings);","plugin-command",1,null);String result=Context.toString(cx.evaluateString(scope,"JSON.stringify({operations:__ops,log:__logs,state:api.state})","plugin-result",1,null));if(result.length()>8*1024*1024)throw new Limit("Plugin result is too large");JSONObject plan=new JSONObject(result);if(plan.getJSONArray("operations").length()>(hook?256:10000))throw new Limit("Too many plugin edits");if(plan.getJSONObject("state").toString().getBytes("UTF-8").length>65536)throw new Limit("Plugin state is too large");return plan;
 }catch(Throwable error){throw new IllegalArgumentException("JavaScript: "+(error.getMessage()==null?error.toString():error.getMessage()),error);}finally{Context.exit();budget.remove();}}
}
